65: /// Computes the 16-bit CRC16-CCITT checksum over `data` with the given initial value.
66: ///
67: /// # Arguments
68: /// * `data` - Byte slice over which to compute the checksum.
69: /// * `init_val` - Initial CRC register value (`0x3692` for DJI primary, `0xFFFF` for fallback).
70: ///
71: /// # Examples
72: /// ```
73: /// use flightreader_core::dat::checksum::{calc_crc16_ccitt, CRC16_INIT_PRIMARY};
74: ///
75: /// let header_and_payload = [0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00];
76: /// let crc = calc_crc16_ccitt(&header_and_payload, CRC16_INIT_PRIMARY);
77: /// assert_eq!(crc, 0x5184);
78: /// ```
79: #[inline]
80: pub fn calc_crc16_ccitt(data: &[u8], init_val: u16) -> u16 {
81:     let mut crc = init_val;
82:     for &b in data {
83:         let idx = (((crc >> 8) ^ (b as u16)) & 0xFF) as usize;
84:         crc = (crc << 8) ^ CRC16_TABLE[idx];
85:     }
86:     crc
87: }
